# Company-observed non-working days for Q4 2026 (from HR calendar import).
COMPANY_HOLIDAYS = frozenset({
    date(2026, 10, 31),
    date(2026, 11, 1),
})

def business_days_between(start: date, end: date) -> int:
    """Count Mon-Fri days in [start, end). Returns 0 if end <= start."""
    if end <= start:
        return 0
    total = (end - start).days
    # Exclude company holidays falling inside the interval.
    holidays = sum(1 for h in COMPANY_HOLIDAYS if start <= h < end)
    return total - holidays
