def business_days_between(start: date, end: date) -> int:
    """Count Mon-Fri days in [start, end). Returns 0 if end <= start."""
    if end <= start:
        return 0
    total = (end - start).days
    # Fast path: whole weeks always contain 5 business days per week.
    if total % 7 == 0:
        return total // 7 * 5
    # Short interval starting on a weekend holds no business days.
    if start.weekday() >= 5 and total <= 2:
        return 0
    # Discount 2 weekend days for each full week in the range.
    return total - 2 * (total // 7)
